 with sync_playwright() as p:
  b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']);host=b.new_page(viewport={'width':1280,'height':900});errors=[];host.on('pageerror',lambda e:errors.append(str(e)));host.goto('http://127.0.0.1:14344');host.evaluate('''async()=>{const{createProject}=await import('/project.js');const p=createProject('3D Tag QA','blank3d');p.camera3d='firstperson';p.objects=p.objects.filter(o=>['character','ground'].includes(o.mesh));localStorage.setItem('playform.projects',JSON.stringify([p]))}''');host.reload();host.locator('.project-open').click();host.locator('.simple-menu summary').nth(1).click();host.locator('[data-nav-action="multiplayer"]').click();host.locator('#host3d [name="mode"]').select_option('tag');host.locator('#host3d [type="submit"]').click();expect(host.locator('#room3d-code')).to_be_visible();code=host.locator('#room3d-code').inner_text();host.locator('#close-room3d').click();guest=b.new_page(viewport={'width':1000,'height':800});guest.on('pageerror',lambda e:errors.append(str(e)));guest.goto('http://127.0.0.1:14344/play?room='+code);expect(guest.locator('.three-clean')).to_be_visible(timeout=15000);expect(host.locator('.studio3d')).to_have_attribute('data-peers','1');expect(guest.locator('.studio3d')).to_have_attribute('data-peers','1');host.wait_for_function('document.querySelector(".studio3d").dataset.it==="false"',timeout=8000);guest.keyboard.down('KeyW');guest.wait_for_timeout(350);guest.keyboard.up('KeyW');assert float(guest.locator('.studio3d').get_attribute('data-z'))<-.5;host.screenshot(path='screenshots/multiplayer-3d-tag.png');assert not errors,errors;b.close();print('PASS 3D host, room-code invite link, two rendered players, movement and server-validated tag transfer',flush=True)
